ALTER TABLE public.project_items ADD COLUMN unlinked_at timestamptz;
GRANT UPDATE ON public.project_items TO authenticated;
CREATE POLICY pi_unlink ON public.project_items FOR UPDATE TO authenticated USING(public.can_manage_project(auth.uid(),project_id)) WITH CHECK(public.can_manage_project(auth.uid(),project_id));
CREATE FUNCTION public.hub_item_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid text; BEGIN IF TG_OP='UPDATE' THEN IF (NEW.id,NEW.project_id,NEW.item_kind,NEW.item_id,NEW.evidence_ref_id) IS DISTINCT FROM (OLD.id,OLD.project_id,OLD.item_kind,OLD.item_id,OLD.evidence_ref_id) OR OLD.unlinked_at IS NOT NULL OR NEW.unlinked_at IS NULL THEN RAISE EXCEPTION 'Only a one-time unlink is allowed'; END IF; IF NOT public.can_manage_project(auth.uid(),NEW.project_id) THEN RAISE EXCEPTION 'Lead or owner required to unlink'; END IF; NEW.unlinked_at:=clock_timestamp(); INSERT INTO public.project_events(project_id,event,actor_id,details) VALUES(NEW.project_id,'item_unlinked',auth.uid(),jsonb_build_object('item_id',NEW.id)); ELSE cid:=public.project_item_case(NEW.item_id,NEW.evidence_ref_id); IF NOT EXISTS(SELECT 1 FROM public.project_cases WHERE project_id=NEW.project_id AND case_id=cid) THEN RAISE EXCEPTION 'Link the case before adding its evidence'; END IF; IF NEW.unlinked_at IS NOT NULL THEN RAISE EXCEPTION 'New links must be active'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER item_guard BEFORE INSERT OR UPDATE ON public.project_items FOR EACH ROW EXECUTE FUNCTION public.hub_item_guard();
CREATE FUNCTION public.hub_output_file_boundary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE project_code text; BEGIN SELECT code INTO project_code FROM public.projects WHERE id=NEW.project_id; IF NEW.location IS NOT NULL AND NEW.location NOT LIKE 'device:%' AND NEW.location NOT LIKE 'projects/'||project_code||'/outputs/'||NEW.id::text||'/%' THEN RAISE EXCEPTION 'Output file must belong to this project and output'; END IF; IF NEW.kind='evidence_bundle' AND NEW.location IS NOT NULL AND EXISTS(SELECT 1 FROM public.project_items WHERE project_id=NEW.project_id AND item_kind='home_ref' AND unlinked_at IS NULL) AND NEW.location NOT LIKE 'device:%' THEN RAISE EXCEPTION 'Home-vault bundles must stay on the device'; END IF; RETURN NEW; END $$;
CREATE TRIGGER output_file_boundary BEFORE INSERT OR UPDATE ON public.project_outputs FOR EACH ROW EXECUTE FUNCTION public.hub_output_file_boundary();
CREATE FUNCTION public.hub_project_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.id,NEW.client_id,NEW.code,NEW.created_by) IS DISTINCT FROM (OLD.id,OLD.client_id,OLD.code,OLD.created_by) THEN RAISE EXCEPTION 'Project identity and code cannot change'; END IF; RETURN NEW; END $$; CREATE TRIGGER project_identity BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.hub_project_identity();
CREATE FUNCTION public.hub_storage_project(path text,write_access boolean) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN path NOT LIKE 'projects/%' THEN true ELSE EXISTS(SELECT 1 FROM public.projects p WHERE p.code=split_part(path,'/',2) AND CASE WHEN write_access THEN public.can_work_project(auth.uid(),p.id) ELSE public.can_access_project(auth.uid(),p.id) END AND (NOT write_access OR NOT EXISTS(SELECT 1 FROM public.project_items i JOIN public.project_outputs o ON o.project_id=i.project_id WHERE i.project_id=p.id AND i.item_kind='home_ref' AND i.unlinked_at IS NULL AND o.kind='evidence_bundle' AND o.id::text=split_part(path,'/',4)))) END $$;
REVOKE ALL ON FUNCTION public.hub_storage_project(text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hub_storage_project(text,boolean) TO authenticated,service_role;
CREATE POLICY project_storage_read_boundary ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'evidence' OR public.hub_storage_project(name,false));
CREATE POLICY project_storage_write_boundary ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'evidence' OR public.hub_storage_project(name,true));
REVOKE ALL ON FUNCTION public.hub_item_guard(),public.hub_output_file_boundary(),public.hub_project_identity() FROM PUBLIC,anon,authenticated;